        input: CellStepInputV1, before: CircuitCellTimeV1) -> Result<CircuitCellExecutionV1, CircuitCellErrorV1>
    { self.0.original_execution(admission, input, before).map_err(|_| CircuitCellErrorV1::ReconciliationRequired) }
}

